"use client"

import { RouteError } from "@/components/route-error"

export default function RouteErrorPage({
  error,
  reset,
}: Readonly<{
  error: Error & { digest?: string }
  reset: () => void
}>) {
  return <RouteError error={error} reset={reset} />
}

import { RouteLoading } from "@/components/route-loading"

export default function Loading() {
  return <RouteLoading />
}

import {
  ArchiveIcon,
  CalendarBlankIcon,
  FlaskIcon,
  LightbulbIcon,
  MagnifyingGlassIcon,
  TagIcon,
} from "@phosphor-icons/react/dist/ssr"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

import { BOARD_CARDS, BOARD_COLUMNS, type BoardColumn, type CardStatus } from "../_data/board"

const COLUMN_ICON: Record<BoardColumn["icon"], typeof MagnifyingGlassIcon> = {
  MagnifyingGlassIcon,
  LightbulbIcon,
  FlaskIcon,
  ArchiveIcon,
}

const STATUS_STYLE: Record<CardStatus, string> = {
  신규: "border-chart-2/40 bg-chart-2/10 text-chart-2",
  검토중: "border-chart-4/40 bg-chart-4/10 text-chart-4",
  채택: "border-success/40 bg-success/10 text-success",
  보류: "border-border bg-muted text-muted-foreground",
}

/**
 * 보드 탭 — 카테고리 4칼럼 칸반풍 레이아웃(드래그 없음). 각 카드에 상태 배지 ·
 * 태그 · 날짜를 얹어 원본보다 시각 밀도를 높였다. 모바일 1열 → md 2열 → xl 4열로
 * 스택되며 가로 오버플로우가 없다.
 */
export function BoardView() {
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
      {BOARD_COLUMNS.map((column) => {
        const cards = BOARD_CARDS.filter((card) => card.column === column.id)
        const Icon = COLUMN_ICON[column.icon]
        return (
          <section
            key={column.id}
            aria-label={column.label}
            className={cn("flex min-w-0 flex-col gap-3 rounded-lg border border-t-2 border-border bg-muted/30 p-3", column.accent)}
          >
            <header className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
              <Icon size={16} weight="bold" className="text-muted-foreground" aria-hidden />
              {column.label}
              <span className="ml-auto rounded-full bg-background px-2 py-0.5 font-mono text-[10px] font-normal text-muted-foreground ring-1 ring-border">
                {cards.length}
              </span>
            </header>

            <div className="flex flex-col gap-2.5">
              {cards.map((card) => (
                <article
                  key={card.id}
                  className="group flex min-w-0 flex-col gap-2 rounded-md border border-border bg-card p-3 transition-colors hover:border-primary/40 hover:shadow-sm"
                >
                  <div className="flex items-start justify-between gap-2">
                    <h4 className="text-sm font-medium leading-snug text-foreground transition-colors group-hover:text-primary">
                      {card.title}
                    </h4>
                    <span
                      className={cn(
                        "shrink-0 rounded-full border px-1.5 py-0.5 text-[10px] font-medium",
                        STATUS_STYLE[card.status]
                      )}
                    >
                      {card.status}
                    </span>
                  </div>
                  <p className="line-clamp-2 text-xs leading-relaxed text-muted-foreground">{card.summary}</p>
                  <div className="flex flex-wrap items-center gap-1">
                    {card.tags.map((tag) => (
                      <Badge key={tag} variant="ghost" className="gap-1 text-[10px] text-muted-foreground">
                        <TagIcon size={10} aria-hidden />
                        {tag}
                      </Badge>
                    ))}
                  </div>
                  <div className="flex items-center gap-1.5 border-t border-border/60 pt-2 font-mono text-[10px] text-muted-foreground">
                    <CalendarBlankIcon size={11} aria-hidden />
                    {card.date}
                  </div>
                </article>
              ))}
            </div>
          </section>
        )
      })}
    </div>
  )
}

import {
  BroomIcon,
  ClipboardTextIcon,
  ClockIcon,
  FileTextIcon,
  FlaskIcon,
  TagIcon,
} from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"

import { LOG_SESSIONS, groupLogsByDate, type SessionKind } from "../_data/logs"

const KIND_ICON: Record<SessionKind, typeof FileTextIcon> = {
  문서: FileTextIcon,
  리뷰: ClipboardTextIcon,
  정리: BroomIcon,
  실험: FlaskIcon,
}

const KIND_STYLE: Record<SessionKind, string> = {
  문서: "border-chart-1/40 bg-chart-1/10 text-chart-1",
  리뷰: "border-chart-4/40 bg-chart-4/10 text-chart-4",
  정리: "border-chart-2/40 bg-chart-2/10 text-chart-2",
  실험: "border-chart-3/40 bg-chart-3/10 text-chart-3",
}

/**
 * 로그 탭 — 날짜별 세션 타임라인. 날짜 구분선(점 + 라벨) 아래에 세로 연결선과
 * 세션 카드(시각 · 요약 · 종류 배지 · 태그)를 얹는다. 원본 담백함을 보완해
 * 종류별 색 배지와 hover 강조를 추가했다.
 */
export function LogsView() {
  const groups = groupLogsByDate(LOG_SESSIONS)

  return (
    <div className="flex flex-col gap-2">
      {groups.map((group) => (
        <section key={group.date} aria-label={group.date}>
          <div className="relative mt-5 mb-3 pl-9 font-mono text-[11px] font-medium tracking-widest text-muted-foreground uppercase first:mt-0">
            <span className="absolute top-1/2 left-2.5 size-3 -translate-y-1/2 rounded-full border-2 border-card bg-primary" />
            {group.date}
          </div>

          <div className="relative flex flex-col gap-3 pl-9 before:absolute before:top-0 before:bottom-0 before:left-[0.9375rem] before:w-px before:bg-border">
            {group.sessions.map((session) => {
              const Icon = KIND_ICON[session.kind]
              return (
                <article key={session.id} className="group relative">
                  <span className="absolute top-3.5 -left-[1.4375rem] size-2.5 rounded-full border-2 border-card bg-muted-foreground/50 transition-colors group-hover:bg-primary" />
                  <div className="flex min-w-0 flex-col gap-1.5 rounded-lg border border-border bg-card p-3.5 transition-colors hover:border-primary/40 hover:shadow-sm">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="flex items-center gap-1 font-mono text-[11px] text-muted-foreground">
                        <ClockIcon size={12} aria-hidden />
                        {session.time}
                      </span>
                      <span
                        className={cn(
                          "inline-flex items-center gap-1 rounded-full border px-1.5 py-0.5 text-[10px] font-medium",
                          KIND_STYLE[session.kind]
                        )}
                      >
                        <Icon size={11} weight="bold" aria-hidden />
                        {session.kind}
                      </span>
                    </div>
                    <h4 className="text-sm font-medium text-foreground transition-colors group-hover:text-primary">
                      {session.title}
                    </h4>
                    <p className="text-xs leading-relaxed text-muted-foreground">{session.summary}</p>
                    <div className="flex flex-wrap items-center gap-1 pt-0.5">
                      {session.tags.map((tag) => (
                        <span
                          key={tag}
                          className="inline-flex items-center gap-1 rounded border border-border px-1.5 text-[10px] text-muted-foreground"
                        >
                          <TagIcon size={9} aria-hidden />
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>
                </article>
              )
            })}
          </div>
        </section>
      ))}
    </div>
  )
}

"use client"

import * as React from "react"
import {
  CalendarBlankIcon,
  ClockIcon,
  HashIcon,
  ListDashesIcon,
  TagIcon,
  UserIcon,
} from "@phosphor-icons/react/dist/ssr"

import { Badge } from "@/components/ui/badge"
import { TreeView } from "@/components/tree-view"
import { cn } from "@/lib/utils"

import {
  WIKI_DEFAULT_DOC,
  WIKI_DEFAULT_EXPANDED,
  WIKI_DOCS,
  WIKI_TREE,
  type WikiDoc,
} from "../_data/wiki"

const STATUS_VARIANT: Record<WikiDoc["status"], "default" | "secondary" | "outline"> = {
  정식: "default",
  검토중: "secondary",
  초안: "outline",
}

/**
 * 위키 탭 — 좌측 tree-view 문서 트리 + 우측 마크다운풍 본문 + 우측 TOC.
 * 트리 선택 상태를 소유하고, 선택 문서의 섹션에서 목차를 파생한다. 모바일에서는
 * 트리 → 본문 → 목차 순으로 세로 스택된다.
 */
export function WikiView() {
  const [selectedId, setSelectedId] = React.useState(WIKI_DEFAULT_DOC)
  const doc = WIKI_DOCS[selectedId] ?? WIKI_DOCS[WIKI_DEFAULT_DOC]

  return (
    <div className="grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,15rem)_minmax(0,1fr)_minmax(0,12rem)]">
      {/* 문서 트리 */}
      <aside className="flex flex-col gap-2">
        <p className="flex items-center gap-1.5 px-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
          <ListDashesIcon size={13} weight="bold" aria-hidden />
          문서 트리
        </p>
        <TreeView
          nodes={WIKI_TREE}
          selectedId={selectedId}
          defaultExpandedIds={WIKI_DEFAULT_EXPANDED}
          onSelectedIdChange={(id) => {
            if (WIKI_DOCS[id]) setSelectedId(id)
          }}
          aria-label="위키 문서 트리"
        />
      </aside>

      {/* 본문 */}
      <article className="min-w-0 rounded-lg border border-border bg-card p-5 sm:p-6">
        <header className="flex flex-col gap-3 border-b border-border pb-4">
          <div className="flex flex-wrap items-center gap-2">
            <Badge variant={STATUS_VARIANT[doc.status]}>{doc.status}</Badge>
            <Badge variant="outline">{doc.category}</Badge>
          </div>
          <h3 className="text-xl font-semibold tracking-tight text-foreground">{doc.title}</h3>
          <dl className="flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs text-muted-foreground">
            <div className="flex items-center gap-1.5">
              <UserIcon size={13} aria-hidden />
              <dt className="sr-only">작성</dt>
              <dd>{doc.author}</dd>
            </div>
            <div className="flex items-center gap-1.5">
              <CalendarBlankIcon size={13} aria-hidden />
              <dt className="sr-only">수정일</dt>
              <dd className="font-mono">{doc.updated}</dd>
            </div>
            <div className="flex items-center gap-1.5">
              <ClockIcon size={13} aria-hidden />
              <dt className="sr-only">읽기 시간</dt>
              <dd>{doc.readMinutes}분 읽기</dd>
            </div>
          </dl>
          <div className="flex flex-wrap items-center gap-1.5">
            {doc.tags.map((tag) => (
              <span
                key={tag}
                className="inline-flex items-center gap-1 rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground transition-colors hover:border-primary/40 hover:text-foreground"
              >
                <TagIcon size={11} aria-hidden />
                {tag}
              </span>
            ))}
          </div>
        </header>

        <div className="flex flex-col gap-6 pt-5">
          {doc.sections.map((section) => (
            <section key={section.id} id={`sec-${section.id}`} className="flex flex-col gap-2">
              <h4
                className={cn(
                  "group flex items-center gap-1.5 font-semibold tracking-tight text-foreground",
                  section.level === 2 ? "text-base" : "text-sm"
                )}
              >
                <HashIcon
                  size={section.level === 2 ? 15 : 13}
                  className="text-muted-foreground/50 transition-colors group-hover:text-primary"
                  aria-hidden
                />
                {section.heading}
              </h4>
              {section.paragraphs.map((para, i) => (
                <p key={i} className="text-sm leading-relaxed text-muted-foreground">
                  {para}
                </p>
              ))}
            </section>
          ))}
        </div>
      </article>

      {/* 목차(TOC) */}
      <aside className="hidden lg:block">
        <div className="sticky top-4 flex flex-col gap-2">
          <p className="flex items-center gap-1.5 px-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
            <ListDashesIcon size={13} weight="bold" aria-hidden />
            목차
          </p>
          <nav aria-label="문서 목차" className="flex flex-col gap-0.5 border-l border-border">
            {doc.sections.map((section) => (
              <a
                key={section.id}
                href={`#sec-${section.id}`}
                className={cn(
                  "-ml-px border-l-2 border-transparent py-1 text-xs text-muted-foreground transition-colors hover:border-primary hover:text-foreground",
                  section.level === 2 ? "pl-3" : "pl-6"
                )}
              >
                {section.heading}
              </a>
            ))}
          </nav>
        </div>
      </aside>
    </div>
  )
}

/**
 * 지식관리 콘솔 · 로그 데모 데이터 — 순수 데이터 모듈. 날짜별로 그룹핑된 작업
 * 세션 10건. 타임라인(날짜 구분선 + 시각·요약·태그) 렌더에 쓴다. 전부 가상
 * 콘텐츠(실프로젝트·개인정보 미포함). 실제 연동 시 이 파일을 교체한다.
 */

/** 세션 종류 — 아이콘·색 구분에 쓴다. */
export type SessionKind = "문서" | "리뷰" | "정리" | "실험"

/** 작업 세션 한 건. */
