  },
]

/** 날짜 그룹(최신 날짜 우선). */
export interface LogGroup {
  date: string
  sessions: LogSession[]
}

/** 세션을 날짜별로 묶어 최신 날짜·최신 시각이 먼저 오도록 정렬한다. */
export function groupLogsByDate(sessions: LogSession[]): LogGroup[] {
  const byDate = new Map<string, LogSession[]>()
  for (const session of sessions) {
    const bucket = byDate.get(session.date) ?? []
    bucket.push(session)
    byDate.set(session.date, bucket)
  }
  return [...byDate.entries()]
    .sort((a, b) => (a[0] < b[0] ? 1 : -1))
    .map(([date, group]) => ({
      date,
      sessions: [...group].sort((a, b) => (a.time < b.time ? 1 : -1)),
    }))
}

/**
 * 지식관리 콘솔 · 위키 데모 데이터 — 순수 데이터 모듈(컴포넌트 로직 없음).
 * 좌측 문서 트리(tree-view)와 우측 본문·TOC 렌더에 함께 쓰인다. 전부 가상
 * 콘텐츠이며 특정 기업·인물·실프로젝트명을 포함하지 않는다. 실제 연동 시 이
 * 파일을 문서 저장소에서 로드한 트리/본문으로 교체한다.
 */

import type { TreeNode } from "@/components/tree-view"

/** 본문 섹션 — heading(레벨 2~3)과 문단들. id 는 TOC 앵커로 쓴다. */
export interface WikiSection {
  id: string
  /** 헤딩 텍스트. */
  heading: string
  /** 2 또는 3(들여쓰기 TOC 용). */
  level: 2 | 3
  /** 문단 텍스트 목록. */
  paragraphs: string[]
}

/** 위키 문서 한 건 — 메타 + 본문 섹션. */
export interface WikiDoc {
  id: string
  /** 문서 제목(본문 상단 h1). */
  title: string
  /** 분류 라벨(배지). */
  category: string
  /** 최종 수정 일자(YYYY-MM-DD). */
  updated: string
  /** 작성 역할(가상, 개인명 아님). */
  author: string
  /** 예상 읽기 시간(분). */
  readMinutes: number
  /** 상태 배지: 정식/초안/검토중. */
  status: "정식" | "초안" | "검토중"
  /** 태그 목록. */
  tags: string[]
  /** 본문 섹션. */
  sections: WikiSection[]
}

/**
 * 좌측 문서 트리. tree-view 의 TreeNode 규격(id/label/children?)을 그대로
 * 쓴다. 리프 노드의 id 는 WIKI_DOCS 의 키와 일치한다.
 */
export const WIKI_TREE: TreeNode[] = [
